-- Separate stores and people keep inbox expectations independent of training fixtures.
insert into auth.users(id,email,email_confirmed_at) select ('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'notice'||n||'@example.test',now() from generate_series(60,64)n;
insert into public.profiles(user_id,full_name) select id,'Notice person '||right(id::text,2) from auth.users where email like 'notice%@example.test';
insert into public.organizations(id,name,time_zone) values('10000000-0000-0000-0000-000000000060','Notice A','Pacific/Kiritimati'),('10000000-0000-0000-0000-000000000061','Notice B','America/New_York');
insert into public.organization_memberships(id,organization_id,user_id,email,role)
select ('20000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,case when n<63 then '10000000-0000-0000-0000-000000000060' else '10000000-0000-0000-0000-000000000061' end::uuid,('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'notice'||n||'@example.test',case when n in(60,63) then 'manager' else 'employee' end from generate_series(60,64)n;
insert into public.training_assignments(id,organization_id,membership_id,course_id,due_date,assigned_by)
select ('a0000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'10000000-0000-0000-0000-000000000060',('20000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'c1000000-0000-4000-8000-000000000001',(now() at time zone 'Pacific/Kiritimati')::date+30,'00000000-0000-0000-0000-000000000060' from generate_series(61,62)n;
set role authenticated;
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000061';
insert into test.codes values('notice-first',public.get_my_training_notifications('10000000-0000-0000-0000-000000000060')::text);
select test.ok((select (code::jsonb->>'unread_count')::int=1 and jsonb_array_length(code::jsonb->'items')=1 from test.codes where label='notice-first'),'employee sees only own assignment, not teammate assignments');
select test.ok(public.get_my_training_notifications('10000000-0000-0000-0000-000000000060')->'items'->0->>'id'=(select code::jsonb->'items'->0->>'id' from test.codes where label='notice-first'),'repeated notification reads keep a stable event ID');
select test.rejects('select * from private.training_notifications','permission denied','raw inbox records are inaccessible to browser roles');
select test.rejects($q$select public.get_my_training_notifications('10000000-0000-0000-0000-000000000061')$q$,'Active store membership required','cross-store inbox request is denied');
select test.rejects($q$select public.mark_training_notifications_read('10000000-0000-0000-0000-000000000061',mark_all=>true)$q$,'Active store membership required','cross-store notification mutation is denied');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000062';
select public.mark_training_notifications_read('10000000-0000-0000-0000-000000000060',array[(select (code::jsonb->'items'->0->>'id')::uuid from test.codes where label='notice-first')]);
select test.ok((public.get_my_training_notifications('10000000-0000-0000-0000-000000000060')->>'unread_count')::int=1,'teammate has an independent inbox');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000061';
select test.ok((public.get_my_training_notifications('10000000-0000-0000-0000-000000000060')->>'unread_count')::int=1,'teammate cannot mark another employee notification read');
select public.mark_training_notifications_read('10000000-0000-0000-0000-000000000060',mark_all=>true);
select test.ok((public.get_my_training_notifications('10000000-0000-0000-0000-000000000060')->>'unread_count')::int=0,'read status persists across fetching the inbox');
reset role;
update public.training_assignments set due_date=(now() at time zone 'Pacific/Kiritimati')::date+3 where id='a0000000-0000-0000-0000-000000000061';
set role authenticated;
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000061';
select test.ok((public.get_my_training_notifications('10000000-0000-0000-0000-000000000060')->>'unread_count')::int=2,'changed deadline and three-day reminder create fresh notifications');
select test.ok(exists(select 1 from jsonb_array_elements(public.get_my_training_notifications('10000000-0000-0000-0000-000000000060')->'items')n where n->>'title'='Training due soon'),'three-day deadline reminder is present');
select public.mark_training_notifications_read('10000000-0000-0000-0000-000000000060',mark_all=>true);
select test.ok((public.get_my_training_notifications('10000000-0000-0000-0000-000000000060')->>'unread_count')::int=0,'refresh never duplicates acknowledged reminders');
reset role;
update public.training_assignments set due_date=(now() at time zone 'Pacific/Kiritimati')::date+1 where id='a0000000-0000-0000-0000-000000000061';
set role authenticated;
select test.ok(exists(select 1 from jsonb_array_elements(public.get_my_training_notifications('10000000-0000-0000-0000-000000000060')->'items')n where n->>'title'='Training due tomorrow'),'day-before reminder uses store-local date');
reset role;
update public.training_assignments set due_date=(now() at time zone 'Pacific/Kiritimati')::date where id='a0000000-0000-0000-0000-000000000061';
set role authenticated;
select test.ok(exists(select 1 from jsonb_array_elements(public.get_my_training_notifications('10000000-0000-0000-0000-000000000060')->'items')n where n->>'title'='Training due today'),'same-day reminder uses store-local date');
reset role;
update public.training_assignments set due_date=(now() at time zone 'Pacific/Kiritimati')::date-1 where id='a0000000-0000-0000-0000-000000000061';
insert into public.training_attempts(assignment_id,attempt_number,submission_key,correct_count,question_count,score,passed)
select 'a0000000-0000-0000-0000-000000000061',n,gen_random_uuid(),0,5,0,false from generate_series(1,3)n;
set role authenticated;
select test.ok(exists(select 1 from jsonb_array_elements(public.get_my_training_notifications('10000000-0000-0000-0000-000000000060')->'items')n where n->>'title'='Training overdue'),'overdue reminder is present');
select test.ok(exists(select 1 from jsonb_array_elements(public.get_my_training_notifications('10000000-0000-0000-0000-000000000060')->'items')n where n->>'kind'='help_needed' and n->>'target_view'='course'),'employee receives a help reminder after three failures');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000060';
insert into test.codes values('notice-manager',public.get_my_training_notifications('10000000-0000-0000-0000-000000000060')::text);
select test.ok((select jsonb_array_length(code::jsonb->'items')=1 and code::jsonb->'items'->0->>'target_view'='home' and code::jsonb->'items'->0->>'body' like 'Notice person 61%' from test.codes where label='notice-manager'),'manager receives own-store help request with employee actual name');
select test.ok((select code not like '%selected_option%' and code not like '%correct_option%' and code not like '%score%' from test.codes where label='notice-manager'),'manager notification does not reveal individual quiz answers or score');
select public.unlock_training_retry('a0000000-0000-0000-0000-000000000061','Reviewed safe product research together');
select test.ok(jsonb_array_length(public.get_my_training_notifications('10000000-0000-0000-0000-000000000060')->'items')=0,'manager help reminder resolves after an unlock');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000061';
select test.ok(exists(select 1 from jsonb_array_elements(public.get_my_training_notifications('10000000-0000-0000-0000-000000000060')->'items')n where n->>'kind'='retry_unlocked'),'employee receives newly available retry notification');
select test.ok(not exists(select 1 from jsonb_array_elements(public.get_my_training_notifications('10000000-0000-0000-0000-000000000060')->'items')n where n->>'kind'='help_needed'),'employee locked notice resolves after manager assistance');
reset role;
update public.training_assignments set completed_at=now() where id='a0000000-0000-0000-0000-000000000061';
set role authenticated;
select test.ok(jsonb_array_length(public.get_my_training_notifications('10000000-0000-0000-0000-000000000060')->'items')=0,'completed training removes assignment, overdue, and retry reminders');
reset role;
insert into public.training_competitions(id,organization_id,course_id,name,start_date,end_date,time_zone,starts_at,ends_at,reward,created_by)
values('b0000000-0000-0000-0000-000000000060','10000000-0000-0000-0000-000000000060','c1000000-0000-4000-8000-000000000001','Notification challenge',current_date,current_date+2,'UTC',now()-interval '1 hour',now()+interval '1 day','Lunch','00000000-0000-0000-0000-000000000060');
insert into public.training_competition_participants(competition_id,organization_id,course_id,membership_id,assignment_id,display_name)
values('b0000000-0000-0000-0000-000000000060','10000000-0000-0000-0000-000000000060','c1000000-0000-4000-8000-000000000001','20000000-0000-0000-0000-000000000061','a0000000-0000-0000-0000-000000000061','Notice person 61');
insert into private.training_challenge_attempts(competition_id,membership_id,submission_key,attempt_number,points,passed,result)
select 'b0000000-0000-0000-0000-000000000060','20000000-0000-0000-0000-000000000061',gen_random_uuid(),n,0,false,'{}'::jsonb from generate_series(1,3)n;
set role authenticated;
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000060';
select test.ok(exists(select 1 from jsonb_array_elements(public.get_my_training_notifications('10000000-0000-0000-0000-000000000060')->'items')n where n->>'kind'='challenge_help' and n->>'target_view'='competitions'),'manager receives failed competition retry help notice');
select public.unlock_training_challenge('b0000000-0000-0000-0000-000000000060','20000000-0000-0000-0000-000000000061','Reviewed the challenge material together');
select test.ok(jsonb_array_length(public.get_my_training_notifications('10000000-0000-0000-0000-000000000060')->'items')=0,'competition help notice resolves after unlock');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000061';
select test.ok(exists(select 1 from jsonb_array_elements(public.get_my_training_notifications('10000000-0000-0000-0000-000000000060')->'items')n where n->>'kind'='challenge_retry'),'competition retry unlock notifies participant separately from original course');
reset role;
update public.training_competitions set ended_early_at=now() where id='b0000000-0000-0000-0000-000000000060';
set role authenticated;
select test.ok(jsonb_array_length(public.get_my_training_notifications('10000000-0000-0000-0000-000000000060')->'items')=0,'closed competition stops retry notifications');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000001';
select test.ok(jsonb_array_length(public.get_my_training_notifications('10000000-0000-0000-0000-000000000060')->'items')=0,'platform admin cannot view employees inboxes automatically');
reset role;
update public.organization_memberships set status='inactive',deactivated_at=now() where id='20000000-0000-0000-0000-000000000062';
set role authenticated;
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000062';
select test.rejects($q$select public.get_my_training_notifications('10000000-0000-0000-0000-000000000060')$q$,'Active store membership required','removed employee cannot retrieve old inbox');
select test.rejects($q$select public.mark_training_notifications_read('10000000-0000-0000-0000-000000000060',mark_all=>true)$q$,'Active store membership required','removed employee cannot alter old inbox');
reset role;
select test.ok(not has_function_privilege('anon','public.get_my_training_notifications(uuid)','execute'),'anonymous notification reads denied');
select test.ok(not has_function_privilege('authenticated','private.training_notification_candidates(uuid)','execute'),'private notification generator cannot be called to bypass access checks');
select 'Passed training notifications: recipients, privacy, deadlines, retries, read status, and resolution ('||count(*)||' total SQL assertions).' from test.results;
